INSERT INTO content_versions (status, data, note, created_by, published_at) VALUES ('published', '{"announcement":{"enabled":true,"messages":[{"text":"Free shipping above ₹999","link":"/shop"},{"text":"Easy returns within 7 days","link":"/policies/returns"}]},"home":{"sections":[{"id":"hero","type":"hero","enabled":true,"data":{"eyebrow":"Contemporary Ethnic Wear","title":"Everyday Styles for","titleAccent":"Modern Women","body":"Kurtas, co-ord sets and dresses, thoughtfully curated for your everyday story.","ctaLabel":"Shop New Arrivals","ctaLink":"/shop?sort=new","secondaryLabel":"Visit our boutique","secondaryLink":"/visit","image":"med_herolead"}},{"id":"categories","type":"categories","enabled":true,"data":{"heading":"Shop by *category*","items":[{"category":"cat_kurtas","image":"med_catkurtas"},{"category":"cat_coords","image":"med_catcoords"},{"category":"cat_dresses","image":"med_catdresses"},{"category":"cat_tops","image":"med_cattops"},{"category":"cat_bottoms","image":"med_catbottoms"}]}},{"id":"new-arrivals","type":"products","enabled":true,"data":{"heading":"Just *landed*","linkLabel":"All new arrivals","source":"newest","collection":null,"category":null,"count":8}},{"id":"occasions","type":"occasions","enabled":true,"data":{"heading":"Dressed for every *moment*","items":[{"collection":"col_everyday","title":"Everyday Edit","image":"med_v2_everyday"},{"collection":"col_festive","title":"Festive Edit","image":"med_v2_festive"},{"collection":"col_work","title":"Work Edit","image":"med_v2_work"}]}},{"id":"boutique","type":"boutique","enabled":false,"data":{"heading":"Try it on *in person*","body":"Step into our boutique to explore the full collection, feel the fabrics and find your perfect fit with our stylists.","image":"med_v2_boutique"}},{"id":"instagram","type":"instagram","enabled":true,"data":{"heading":"Style *inspiration*","handle":"","images":[{"image":"med_v2_style_lavender","caption":"","link":""},{"image":"med_v2_style_mustard","caption":"","link":""},{"image":"med_v2_style_ivory","caption":"","link":""},{"image":"med_v2_style_maroon","caption":"","link":""}]}}]},"boutique":{"title":"Try it on *in person*","body":"Step into our boutique to explore the full collection, feel the fabrics and find your perfect fit with our stylists.","image":"med_v2_boutique"},"trust":{"items":[{"icon":"truck","title":"Free Shipping","body":"Above ₹999"},{"icon":"returns","title":"Easy Returns","body":"Within 7 days"},{"icon":"shield","title":"Secure Payments","body":"UPI, Cards & more"},{"icon":"chat","title":"Need Help?","body":"Chat on WhatsApp"}]},"newsletter":{"title":"Get Style Updates","body":"New arrivals and exclusive offers, straight to your inbox."},"about":{"title":"Made for the way you live","intro":"Femia is a women''s wear boutique at Choice Mall, Sreekandapuram, Kannur: kurtas, co-ords and dresses you will reach for again and again.","body":"DRAFT: replace with the owner''s story before launch.\n\nWe started Femia to make beautiful, comfortable ethnic wear easy to find. Every piece is chosen for its fabric, its fit and how it feels at the end of a long day.","image":"med_v2_about"},"policies":{"shipping":"DRAFT for client review.\n\n## Where we deliver\nWe currently deliver within Kerala.\n\n## Charges\nFree shipping on orders above ₹999. A flat ₹79 applies below that.\n\n## Timelines\nOrders are packed within 1–2 working days and usually arrive in 2–5 days.","returns":"DRAFT for client review.\n\n## Returns within 7 days\nUnworn items with tags attached can be returned within 7 days of delivery. Message us on WhatsApp with your order number to start a return.","privacy":"DRAFT for client review (DPDP Act 2023).\n\nWe collect your name, phone, email and address only to deliver your order and keep you updated. We never sell your data.","terms":"DRAFT for client review.\n\nBy placing an order you agree to these terms.","contact":"Phone & WhatsApp: +91 73068 93072\nInstagram: @femia__boutique\nBoutique: Choice Mall, Sreekandapuram, Kannur, Kerala."},"sizeGuide":{"chart":"| Size | Bust (in) | Waist (in) | Hip (in) |\n|---|---|---|---|\n| XS | 32 | 26 | 35 |\n| S | 34 | 28 | 37 |\n| M | 36 | 30 | 39 |\n| L | 38 | 32 | 41 |\n| XL | 40 | 34 | 43 |\n| XXL | 42 | 36 | 45 |","howToMeasure":"Measure around the fullest part of your bust, the narrowest part of your waist and the fullest part of your hips. If you are between sizes, choose the larger one."}}', 'Seed content', 'seed', '2026-11-16T19:15:28.277Z');
